1	/**
2	 * The margins, used the way Google Docs uses them.
3	 *
4	 * Right margin: the one live tool, pinned level with the passage it is about
5	 * and joined to it by a hairline, so it reads as a note on *that* passage.
6	 * Left margin: "Your tools" — the tools the writer kept — and a faint tick
7	 * beside each paragraph they have been working hard at.
8	 *
9	 * Both rails sit inside the page canvas, so they scroll with the page. When
10	 * the window is too narrow to give a margin room, the rails step aside: the
11	 * tool opens as a card under its passage instead and the shelf folds away.
12	 */
13	import {
14	  $,
15	  component$,
16	  useSignal,
17	  useStore,
18	  useVisibleTask$,
19	} from "@qwik.dev/core";
20	import {
21	  inFlowController,
22	  inFlowSnapshot,
23	} from "../editor/extensions/struggle-tracker";
24	import {
25	  IN_FLOW_EVENT,
26	  type ActiveTool,
27	  type InFlowSnapshot,
28	} from "../../utils/in-flow-tools";
29	import {
30	  loadSavedTools,
31	  removeSavedTool,
32	  SAVED_TOOLS_EVENT,
33	  type SavedTool,
34	} from "../../utils/saved-tools";
35	import { TOOL_LABELS } from "../../utils/struggle-signals";
36	import { configFor, ToolRenderer } from "./tool-renderer";
37	
38	const CARD_WIDTH = 296;
39	const RAIL_GAP = 28;
40	const SHELF_WIDTH = 176;
41	
42	interface RailState {
43	  active: ActiveTool | null;
44	  /** Card top relative to the canvas, or null before measuring. */
45	  cardTop: number | null;
46	  /** Passage top/height relative to the canvas, for the connector. */
47	  anchorTop: number;
48	  anchorHeight: number;
49	  ticks: number[];
50	  mode: "rail" | "popover";
51	  shelf: boolean;
52	  /** Popover mode: fixed viewport position. */
53	  popLeft: number;
54	  popTop: number;
55	  saved: SavedTool[];
56	  naming: boolean;
57	  name: string;
58	  keepError: string;
59	}
60	
61	export const MarginRails = component$<{ zen: boolean; readOnly?: boolean }>(
62	  (props) => {
63	    const root = useSignal<HTMLDivElement>();
64	    const state = useStore<RailState>({
65	      active: null,
66	      cardTop: null,
67	      anchorTop: 0,
68	      anchorHeight: 0,
69	      ticks: [],
70	      mode: "rail",
71	      shelf: true,
72	      popLeft: 0,
73	      popTop: 0,
74	      saved: [],
75	      naming: false,
76	      name: "",
77	      keepError: "",
78	    });
79	
80	    // eslint-disable-next-line qwik/no-use-visible-task
81	    useVisibleTask$(({ cleanup }) => {
82	      const el = root.value;
83	      const canvas = el?.closest<HTMLElement>(".page-canvas");
84	      const scroller = canvas?.parentElement;
85	      if (!el || !canvas || !scroller) return;
86	      let tickPositions: number[] = [];
87	      let frame = 0;
88	
89	      const measure = () => {
90	        cancelAnimationFrame(frame);
91	        frame = requestAnimationFrame(() => {
92	          const canvasRect = canvas.getBoundingClientRect();
93	          const scrollerRect = scroller.getBoundingClientRect();
94	          const right = scrollerRect.right - canvasRect.right;
95	          const left = canvasRect.left - scrollerRect.left;
96	          state.mode = right >= CARD_WIDTH + RAIL_GAP + 8 ? "rail" : "popover";
97	          state.shelf = left >= SHELF_WIDTH + RAIL_GAP;
98	
99	          const controller = inFlowController();
100	          const rect = state.active ? controller?.anchorRect() : null;
101	          if (rect) {
102	            state.anchorTop = rect.top - canvasRect.top;
103	            state.anchorHeight = rect.height;
104	            state.cardTop = Math.max(0, state.anchorTop - 6);
105	            state.popLeft = Math.max(
106	              12,
107	              Math.min(rect.left, window.innerWidth - CARD_WIDTH - 12),
108	            );
109	            state.popTop = Math.max(
110	              12,
111	              Math.min(rect.bottom + 10, window.innerHeight - 120),
112	            );
113	          } else {
114	            state.cardTop = null;
115	          }
116	          state.ticks = tickPositions
117	            .map((pos) => controller?.blockTop(pos))
118	            .filter((top): top is number => typeof top === "number")
119	            .map((top) => top - canvasRect.top);
120	        });
121	      };
122	
123	      const onSnapshot = (detail: InFlowSnapshot) => {
124	        // Plain copies only: the snapshot is shared module state.
125	        state.active = detail.active
126	          ? (JSON.parse(JSON.stringify(detail.active)) as ActiveTool)
127	          : null;
128	        if (!detail.active) {
129	          state.naming = false;
130	          state.keepError = "";
131	        }
132	        tickPositions = detail.ticks;
133	        measure();
134	      };
135	      const onEvent = (event: Event) =>
136	        onSnapshot((event as CustomEvent<InFlowSnapshot>).detail);
137	      const onSaved = (event: Event) => {
138	        state.saved = (event as CustomEvent<SavedTool[]>).detail ?? [];
139	      };
140	
141	      onSnapshot(inFlowSnapshot());
142	      void loadSavedTools().then((tools) => {
143	        state.saved = tools;
144	      });
145	      window.addEventListener(IN_FLOW_EVENT, onEvent);
146	      window.addEventListener(SAVED_TOOLS_EVENT, onSaved);
147	      window.addEventListener("twyne:content", measure);
148	      window.addEventListener("resize", measure);
149	      // The popover is fixed to the viewport, so it must follow a scroll.
150	      const onScroll = () => {
151	        if (state.active && state.mode === "popover") measure();
152	      };
153	      scroller.addEventListener("scroll", onScroll, { passive: true });
154	      const observer = new ResizeObserver(measure);
155	      observer.observe(canvas);
156	      observer.observe(scroller);
157	      cleanup(() => {
158	        cancelAnimationFrame(frame);
159	        window.removeEventListener(IN_FLOW_EVENT, onEvent);
160	        window.removeEventListener(SAVED_TOOLS_EVENT, onSaved);
161	        window.removeEventListener("twyne:content", measure);
162	        window.removeEventListener("resize", measure);
163	        scroller.removeEventListener("scroll", onScroll);
164	        observer.disconnect();
165	      });
166	    });
167	
168	    const keep = $(async () => {
169	      const tool = state.active;
170	      if (!tool) return;
171	      const name = state.name.trim() || TOOL_LABELS[tool.kind];
172	      try {
173	        await inFlowController()?.keep(name, configFor(tool));
174	        state.naming = false;
175	        state.keepError = "";
176	      } catch {
177	        state.keepError = "Couldn't keep it — storage refused the write.";
178	      }
179	    });
180	
181	    if (props.zen || props.readOnly) return <div ref={root} hidden />;
182	
183	    const tool = state.active;
184	    const card = tool && (
185	      <article
186	        class={[
187	          "in-flow-card",
188	          { "in-flow-card--filling": tool.status === "filling" },
189	        ]}
190	        aria-label={`${TOOL_LABELS[tool.kind]} for this passage`}
191	      >
192	        <header class="in-flow-card__head">
193	          <button
194	            type="button"
195	            class="in-flow-card__title"
196	            onClick$={() => inFlowController()?.focusAnchor()}
197	            title="Go to the passage"
198	          >
199	            {TOOL_LABELS[tool.kind]}
200	          </button>
201	          {tool.tentative && (
202	            <span
203	              class="in-flow-card__maybe"
204	              title="The signals were mixed; ignore this if it doesn't fit."
205	            >
206	              maybe
207	            </span>
208	          )}
209	          <button
210	            type="button"
211	            class="in-flow-card__close"
212	            onClick$={() => inFlowController()?.dismiss()}
213	            aria-label="Dismiss this tool"
214	            title="Dismiss — this passage stays quiet for a while"
215	          >
216	            ✕
217	          </button>
218	          <p class="in-flow-card__reason">{tool.reason}</p>
219	        </header>
220	        <ToolRenderer tool={tool} />
221	        {tool.notice && <p class="in-flow-card__notice">{tool.notice}</p>}
222	        <footer class="in-flow-card__foot">
223	          {tool.savedId ? (
224	            <span class="in-flow-quiet">In Your tools</span>
225	          ) : state.naming ? (
226	            <div class="in-flow-row">
227	              <input
228	                class="in-flow-input"
229	                placeholder={TOOL_LABELS[tool.kind]}
230	                value={state.name}
231	                onInput$={(_, el) => {
232	                  state.name = el.value;
233	                }}
234	                onKeyDown$={(event) => {
235	                  if (event.key === "Enter") void keep();
236	                  if (event.key === "Escape") state.naming = false;
237	                }}
238	                aria-label="Name for this tool"
239	              />
240	              <button
241	                type="button"
242	                class="btn-paper in-flow-mini"
243	                onClick$={keep}
244	              >
245	                Keep
246	              </button>
247	            </div>
248	          ) : (
249	            <button
250	              type="button"
251	              class="in-flow-link"
252	              onClick$={() => {
253	                state.naming = true;
254	                state.name = "";
255	              }}
256	              title="Save this tool, as you've set it up, to reuse on any passage"
257	            >
258	              Keep this tool
259	            </button>
260	          )}
261	          {state.keepError && (
262	            <p class="in-flow-card__notice" role="alert">
263	              {state.keepError}
264	            </p>
265	          )}
266	        </footer>
267	      </article>
268	    );
269	
270	    return (
271	      <div ref={root} class="in-flow-rails" aria-live="polite">
272	        {state.shelf && (
273	          <aside class="in-flow-shelf" aria-label="Your tools">
274	            {/* The shelf appears once there is something on it; an empty
275	                placeholder would only push the writer's echoes down the
276	                margin. A tool card's "Keep this tool" introduces it. */}
277	            {state.saved.length > 0 && (
278	              <div class="in-flow-shelf__inner">
279	                <p class="in-flow-label">Your tools</p>
280	                <ul class="in-flow-shelf__list">
281	                  {state.saved.map((saved) => (
282	                    <li key={saved.id}>
283	                      <button
284	                        type="button"
285	                        class="in-flow-shelf__tool"
286	                        onClick$={() => inFlowController()?.openSaved(saved)}
287	                        title={`Use ${saved.name} on the paragraph you're in`}
288	                      >
289	                        <span>{saved.name}</span>
290	                        <small>{TOOL_LABELS[saved.kind]}</small>
291	                      </button>
292	                      <button
293	                        type="button"
294	                        class="in-flow-shelf__remove"
295	                        onClick$={() => void removeSavedTool(saved.id)}
296	                        aria-label={`Remove ${saved.name}`}
297	                      >
298	                        ✕
299	                      </button>
300	                    </li>
301	                  ))}
302	                </ul>
303	              </div>
304	            )}
305	            {state.ticks.map((top) => (
306	              <span
307	                key={`tick-${top}`}
308	                class="in-flow-tick"
309	                style={{ top: `${top}px` }}
310	                aria-hidden="true"
311	              />
312	            ))}
313	          </aside>
314	        )}
315	
316	        {tool && state.cardTop !== null && state.mode === "rail" && (
317	          <>
318	            <span
319	              class="in-flow-connector"
320	              style={{
321	                top: `${state.anchorTop + Math.min(12, state.anchorHeight / 2)}px`,
322	              }}
323	              aria-hidden="true"
324	            />
325	            <div
326	              class="in-flow-rail"
327	              style={{ top: `${state.cardTop}px`, width: `${CARD_WIDTH}px` }}
328	            >
329	              {card}
330	            </div>
331	          </>
332	        )}
333	
334	        {tool && state.cardTop !== null && state.mode === "popover" && (
335	          <div
336	            class="in-flow-popover"
337	            style={{
338	              left: `${state.popLeft}px`,
339	              top: `${state.popTop}px`,
340	              width: `${CARD_WIDTH}px`,
341	            }}
342	          >
343	            {card}
344	          </div>
345	        )}
346	      </div>
347	    );
348	  },
349	);
