1	/**
2	 * The margins as the conductor sees fit to fill them.
3	 *
4	 * Right margin, the room: notes and replies as they are written, sources the
5	 * Apparatus found, the works the draft names, the charter, the dossier's
6	 * amendments. Left margin, the archive: what the writer has written before
7	 * that this passage echoes, and what their dossier already holds.
8	 *
9	 * Every card sits level with the passage it speaks to. Hover one — or hover
10	 * a marked passage in the text — and a proofreader's bracket and a drawn line
11	 * join the card to its passage, and to every other card on that passage.
12	 * Nothing here decides what appears; `flow-conductor.ts` does.
13	 *
14	 * A comment or a persona note is a conversation. Open it — from its card or
15	 * from the chip in the text — and the editor's conversation card unfolds in
16	 * this card's slot while the card steps aside; the cards below make room.
17	 * See `utils/margin-surface.ts` for the handshake.
18	 *
19	 * The desk, at the head of the room, keeps two things that outlast the
20	 * cards. While the page is quiet, the pneumatic post: a capsule tab counting
21	 * what the conductor is holding back, delivered when the writer pauses or
22	 * taps it. When a run of focus ends, the galley slip: what the run set.
23	 */
24	import {
25	  $,
26	  component$,
27	  useSignal,
28	  useStore,
29	  useVisibleTask$,
30	} from "@qwik.dev/core";
31	import { FLOW_LAYOUT_EVENT } from "../../utils/in-flow-events";
32	import {
33	  FLOW_EVENT,
34	  flowController,
35	  flowSnapshot,
36	  type FlowSnapshot,
37	} from "../editor/extensions/flow-conductor";
38	import {
39	  KIND_LABELS,
40	  SIDE_FOR,
41	  stackCards,
42	  type FlowItem,
43	  type FlowItemKind,
44	} from "../../utils/flow-items";
45	import {
46	  FLOW_SESSION_EVENT,
47	  type FlowSession,
48	  type FlowSessionEnd,
49	} from "../../utils/flow-session";
50	import type { FlowMode } from "../../utils/flow-state";
51	import {
52	  MARGIN_SLOT_EVENT,
53	  OPEN_MARGIN_THREAD_EVENT,
54	  registerMarginSurface,
55	  type MarginSlot,
56	  type MarginSlotDetail,
57	  type OpenMarginThreadDetail,
58	} from "../../utils/margin-surface";
59	import { Icon } from "../ui/icon";
60	import { PersonaMasthead } from "../personas/persona-portrait";
61	
62	const ROOM_WIDTH = 268;
63	const ARCHIVE_WIDTH = 212;
64	const GUTTER = 28;
65	/** The editor's conversation card is this wide when there is room for it. */
66	const THREAD_WIDTH = 340;
67	/** Before the unfolded card has rendered, assume it is about this tall. */
68	const THREAD_GUESS = 280;
69	
