71	  item: FlowItem;
72	  top: number;
73	  side: "room" | "archive";
74	}
75	
76	interface Line {
77	  d: string;
78	  color: string;
79	  dashed: boolean;
80	}
81	
82	interface Mark {
83	  x: number;
84	  y: number;
85	  w: number;
86	  h: number;
87	  color: string;
88	}
89	
90	interface Bracket {
91	  d: string;
92	  color: string;
93	}
94	
95	interface SurfaceState {
96	  mode: FlowMode;
97	  enabled: boolean;
98	  items: FlowItem[];
99	  held: number;
100	  expanded: boolean;
101	  peekId: string | null;
102	  hoverId: string | null;
103	  /** The item whose conversation is unfolded over its slot. */
104	  openId: string | null;
105	  /** A conversation with no card (resolved, say) still needs a slot. */
106	  openTop: number | null;
107	  placed: Placed[];
108	  room: "rail" | "dock";
109	  archive: boolean;
110	  lines: Line[];
111	  marks: Mark[];
