162	
163	const runLength = (ms: number) => {
164	  const minutes = Math.round(ms / 60_000);
165	  if (minutes < 1) return "under a minute";
166	  if (minutes < 60) return `${minutes} min`;
167	  const rest = minutes % 60;
168	  return rest
169	    ? `${Math.floor(minutes / 60)} h ${rest} min`
170	    : `${minutes / 60} h`;
171	};
