173	const clip = (text: string, n: number) =>
174	  text.length > n ? `${text.slice(0, n - 1).trimEnd()}…` : text;
175	
176	export const FlowSurface = component$<{ zen: boolean; readOnly?: boolean }>(
177	  (props) => {
178	    const root = useSignal<HTMLDivElement>();
179	    const state = useStore<SurfaceState>({
180	      mode: "working",
181	      enabled: false,
182	      items: [],
183	      held: 0,
184	      expanded: false,
185	      peekId: null,
186	      hoverId: null,
187	      openId: null,
188	      openTop: null,
189	      placed: [],
190	      room: "rail",
191	      archive: true,
192	      lines: [],
193	      marks: [],
194	      brackets: [],
195	      width: 0,
196	      height: 0,
197	      dockBottom: 80,
198	      drafts: {},
199	      busy: {},
200	      notices: {},
201	      autoFocus: false,
202	      heldKinds: {},
203	      arriving: false,
204	      slip: null,
205	      slipExpanded: false,
206	    });
207	
208	    // eslint-disable-next-line qwik/no-use-visible-task
209	    useVisibleTask$(({ cleanup }) => {
210	      const el = root.value;
211	      const canvas = el?.closest<HTMLElement>(".page-canvas");
212	      const scroller = canvas?.parentElement;
213	      if (!el || !canvas || !scroller) return;
214	      let frame = 0;
215	      let latest: FlowSnapshot = flowSnapshot();
216	      let lastSlot = "";
217	      let observedThread: Element | null = null;
218	      const observedCards = new Set<Element>();
219	      let waiters: Array<(slot: MarginSlot | null) => void> = [];
220	      let arrivingTimer: ReturnType<typeof setTimeout> | undefined;
221	      let seenSessionId: string | null = null;
222	
223	      const itemsToShow = (): FlowItem[] => {
224	        const controller = flowController();
225	        const all = controller?.items() ?? [];
226	        const base =
227	          state.expanded && latest.mode !== "flow" ? all : latest.visible;
228	        const list = [...base];
229	        for (const id of [state.peekId, state.openId]) {
230	          const extra = id && all.find((i) => i.id === id);
231	          if (extra && !list.some((i) => i.id === extra.id)) list.push(extra);
232	        }
233	        return list.map((i) => JSON.parse(JSON.stringify(i)) as FlowItem);
234	      };
235	
236	      const threadCard = () =>
237	        state.openId
238	          ? document.querySelector<HTMLElement>(
239	              `[data-margin-item="${CSS.escape(state.openId)}"]`,
240	            )
241	          : null;
242	
243	      const layout = () => {
244	        cancelAnimationFrame(frame);
245	        frame = requestAnimationFrame(() => {
246	          const controller = flowController();
247	          const cards = new Set(
248	            canvas.querySelectorAll(
249	              ".flow-card, .in-flow-rail, .in-flow-shelf__inner, .flow-slip",
250	            ),
251	          );
252	          for (const node of observedCards) {
253	            if (!cards.has(node)) {
254	              observer.unobserve(node);
255	              observedCards.delete(node);
