/* ── The desk: what outlasts the cards ─────────────────────────────────
   Pneumatic post at the head of the room while the page is quiet; the
   galley slip at its foot when a run of focus ends. Both are sticky, so
   they stay in view however long the manuscript. */
.flow-desk {
  position: absolute;
  top: 0;
  bottom: 0;
  left: calc(100% + 28px);
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  pointer-events: none;
}
.flow-desk > * {
  pointer-events: auto;
}
.flow-desk__top {
  position: sticky;
  top: 1rem;
  z-index: var(--z-sticky);
}
.flow-desk__bottom {
  position: sticky;
  bottom: 1rem;
  z-index: var(--z-sticky);
}
.flow-desk--dock {
  animation: margin-unfold 180ms ease-out;
  transition:
    top 160ms ease-out,
    left 160ms ease-out;
}
@keyframes margin-unfold {
  from {
    opacity: 0.4;
    transform: scaleY(0.94);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
@media (prefers-reduced-motion: reduce) {
  .flow-card,
  .flow-overlay__line,
  .flow-work__disc,
  .manuscript-comment-card.is-in-margin,
  [data-flow] .editor-workspace-main > header {
    animation: none;
    transition: none;
  }
  .flow-overlay__line {
    stroke-dashoffset: 0;
  }
}
@media print {
  .flow-surface,
  .flow-dock,
  .flow-desk {
    display: none !important;
  }
}
@media (prefers-reduced-motion: reduce) {
  .flow-slip,
  .flow-post.is-arriving .flow-post__capsule {
    animation: none;
  }
}
